<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { api } from '@/api/client'
type Location={id:number;name:string};type Item={id:number;name?:string;sport?:string;reason?:string;holiday_date?:string;price?:number;status?:string}
const client=useQueryClient();const facilityId=ref<number>();const branchId=ref<number>();const courtId=ref<number>();const kind=ref('holiday');const name=ref('');const sport=ref('');const description=ref('');const date=ref('');const end=ref('');const price=ref<number>();const msg=ref('');const err=ref('');const busy=ref(false);const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];const hours=ref(days.map((_,day_of_week)=>({day_of_week,opens_at:'08:00',closes_at:'22:00',is_closed:false})))
const facilities=useQuery({queryKey:['facilities'],queryFn:async()=>((await api.get('/facilities')).data.data??[])});const branches=useQuery({queryKey:computed(()=>['facility-branches',facilityId.value]),enabled:computed(()=>!!facilityId.value),queryFn:async()=>((await api.get(`/facilities/${facilityId.value}/branches`)).data.data??[])});const courts=useQuery({queryKey:computed(()=>['branch-courts',branchId.value]),enabled:computed(()=>!!branchId.value),queryFn:async()=>((await api.get(`/branches/${branchId.value}/courts`)).data.data??[])});const holidays=useQuery({queryKey:computed(()=>['holidays',branchId.value]),enabled:computed(()=>!!branchId.value),queryFn:async()=>((await api.get(`/branches/${branchId.value}/holidays`)).data.data??[])});const maintenance=useQuery({queryKey:computed(()=>['maintenance',courtId.value]),enabled:computed(()=>!!courtId.value),queryFn:async()=>((await api.get(`/courts/${courtId.value}/maintenance`)).data.data??[])});const rules=useQuery({queryKey:computed(()=>['pricing',courtId.value]),enabled:computed(()=>!!courtId.value),queryFn:async()=>((await api.get(`/courts/${courtId.value}/pricing-rules`)).data.data??[])});const types=useQuery({queryKey:['court-types'],queryFn:async()=>{const r=await api.get('/court-types');return r.data.data?.data??r.data.data??[]}})
const branchList=computed<Location[]>(()=>branches.data.value??[]);const courtList=computed<Location[]>(()=>courts.data.value??[]);const list=computed<Item[]>(()=>kind.value==='holiday'?holidays.data.value??[]:kind.value==='maintenance'?maintenance.data.value??[]:kind.value==='pricing'?rules.data.value??[]:types.data.value??[]);watch(facilityId,()=>{branchId.value=undefined;courtId.value=undefined});watch(branchId,()=>courtId.value=undefined)
async function refresh(){await Promise.all(['holidays','maintenance','pricing','court-types'].map(key=>client.invalidateQueries({queryKey:[key]})))}async function saveHours(){if(!branchId.value){err.value='Select a branch.';return}busy.value=true;try{await api.put(`/branches/${branchId.value}/operating-hours`,{hours:hours.value.map(hour=>({...hour,opens_at:hour.is_closed?null:hour.opens_at,closes_at:hour.is_closed?null:hour.closes_at}))});msg.value='Operating hours saved.'}catch(e:any){err.value=e.response?.data?.message??'Could not save hours.'}finally{busy.value=false}}
async function add(){try{if(kind.value==='holiday'){if(!branchId.value)throw Error('Select a branch.');await api.post(`/branches/${branchId.value}/holidays`,{holiday_date:date.value,name:name.value,is_closed:true})}else if(kind.value==='maintenance'){if(!courtId.value)throw Error('Select a court.');await api.post(`/courts/${courtId.value}/maintenance`,{starts_at:date.value,ends_at:end.value||undefined,reason:name.value})}else if(kind.value==='pricing'){if(!courtId.value)throw Error('Select a court.');await api.post(`/courts/${courtId.value}/pricing-rules`,{name:name.value,price:price.value,is_active:true})}else await api.post('/court-types',{name:name.value,sport:sport.value||undefined,description:description.value||undefined});msg.value='Operational record created.';name.value='';await refresh()}catch(e:any){err.value=e.message==='Select a branch.'||e.message==='Select a court.'?e.message:e.response?.data?.message??'Could not create record.'}}
async function edit(item:Item){try{if(kind.value==='maintenance'){const status=prompt('Status: scheduled, in_progress, completed, or cancelled',item.status??'scheduled');if(!status)return;await api.patch(`/maintenance/${item.id}`,{status})}else if(kind.value==='pricing'){const next=prompt('Price',String(item.price??''));if(!next)return;await api.patch(`/pricing-rules/${item.id}`,{price:Number(next)})}else if(kind.value==='court-type'){const next=prompt('Court type name',item.name);if(!next)return;await api.patch(`/court-types/${item.id}`,{name:next})}else{err.value='To change a holiday, delete it and create a replacement.';return}msg.value='Record updated.';await refresh()}catch(e:any){err.value=e.response?.data?.message??'Could not update record.'}}
async function remove(item:Item){if(!confirm('Delete this record?'))return;try{if(kind.value==='holiday')await api.delete(`/holidays/${item.id}`);else if(kind.value==='pricing')await api.delete(`/pricing-rules/${item.id}`);else if(kind.value==='court-type')await api.delete(`/court-types/${item.id}`);else{err.value='Use Edit to complete or cancel maintenance.';return}msg.value='Record deleted.';await refresh()}catch(e:any){err.value=e.response?.data?.message??'Could not delete record.'}}
</script>
<template><header class="page-header"><div><p class="eyebrow">FACILITY OPERATIONS</p><h1>Operations</h1><p class="muted">Manage operating hours, closures, maintenance, pricing, and court types.</p></div></header><p v-if="msg" class="action-message success">{{msg}}</p><p v-if="err" class="action-message error">{{err}}</p><section class="panel membership-form payment-form"><h2>Location selection</h2><div class="form-grid"><label>Facility<select v-model.number="facilityId"><option :value="undefined">Select facility</option><option v-for="facility in facilities.data.value??[]" :key="facility.id" :value="facility.id">{{facility.name}}</option></select></label><label>Branch<select v-model.number="branchId" :disabled="!facilityId"><option :value="undefined">Select branch</option><option v-for="branch in branchList" :key="branch.id" :value="branch.id">{{branch.name}}</option></select></label><label>Court<select v-model.number="courtId" :disabled="!branchId"><option :value="undefined">Select court</option><option v-for="court in courtList" :key="court.id" :value="court.id">{{court.name}}</option></select></label></div></section><section class="panel membership-form payment-form"><h2>Weekly operating hours</h2><form @submit.prevent="saveHours"><div class="hours-grid"><label v-for="(hour,index) in hours" :key="hour.day_of_week">{{days[index]}}<span><input v-model="hour.opens_at" :disabled="hour.is_closed" type="time"/><input v-model="hour.closes_at" :disabled="hour.is_closed" type="time"/><input v-model="hour.is_closed" type="checkbox"/>Closed</span></label></div><button class="primary-button" :disabled="busy||!branchId">Save hours</button></form></section><section class="membership-top-grid"><article class="panel membership-form"><h2>Manage records</h2><form @submit.prevent="add"><label>Record type<select v-model="kind"><option value="holiday">Holiday</option><option value="maintenance">Maintenance</option><option value="pricing">Pricing rule</option><option value="court-type">Court type</option></select></label><label>Name / reason<input v-model="name"/></label><label v-if="kind==='court-type'">Sport<input v-model="sport" placeholder="e.g. Tennis"/></label><label v-if="kind==='court-type'">Description<textarea v-model="description" rows="2"/></label><label v-if="kind==='holiday'||kind==='maintenance'">Date / start<input v-model="date" :type="kind==='holiday'?'date':'datetime-local'"/></label><label v-if="kind==='maintenance'">End<input v-model="end" type="datetime-local"/></label><label v-if="kind==='pricing'">Price<input v-model.number="price" type="number" min="0"/></label><button class="secondary-button">Add record</button></form></article><article class="panel"><h2>Current {{kind}} records</h2><div class="selection-list"><button v-for="item in list" :key="item.id"><strong>{{item.name||item.reason||`Record #${item.id}`}}</strong><span>{{item.sport||item.holiday_date||item.status||item.price||''}} · <a @click.stop="edit(item)">Edit</a> · <a @click.stop="remove(item)">Delete</a></span></button><p v-if="!list.length" class="muted">Select the appropriate location to load records.</p></div></article></section></template>
